plugins {
    alias(libs.plugins.kotlin.jvm)
    alias(libs.plugins.kotlin.serialization)
    alias(libs.plugins.spotless)
    alias(libs.plugins.versions)
    `java-library`
}

repositories {
    mavenCentral()
}

dependencies {
    api(libs.slf4j.api)
    implementation(libs.kotlinx.serialization.json)
    implementation(libs.clikt)

    testImplementation(libs.junit.jupiter)
    testImplementation(libs.junit.jupiter.params)
    testRuntimeOnly(libs.slf4j.simple)
    testRuntimeOnly("org.junit.platform:junit-platform-launcher")
}

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

tasks.register<JavaExec>("generateDatasetManifest") {
    group = "application"
    description = "Generate dataset-manifest.json for IMDb TSV/GZ files."
    classpath = sourceSets["main"].runtimeClasspath
    mainClass = "com.kimdb.tsv.GenerateDatasetManifestKt"
    workingDir = rootProject.projectDir
}

sourceSets {
    test {
        resources {
            srcDir(rootProject.layout.projectDirectory.dir("src/main/resources"))
        }
    }
}

tasks.withType<Test>().configureEach {
    useJUnitPlatform()

    // Stable defaults for IMDb-scale integration tests:
    // - single fork avoids concurrent large in-memory datasets
    // - periodic fork limits long-lived heap growth
    maxParallelForks = 1
    forkEvery = 12
    minHeapSize = "1g"
    maxHeapSize = "16g"
}

spotless {
    kotlin {
        target("src/**/*.kt")
        ktlint()
    }
    kotlinGradle {
        target("*.gradle.kts")
        ktlint()
    }
}
